#!/usr/bin/env node

/**
 * P1-3 최종 솔루션: Git Clone으로 모든 프로젝트 동기화
 *
 * GOGS API 토큰 인증 불가 → git clone + git log로 우회
 * 1. 매칭된 repo_url을 사용
 * 2. Shallow clone (--depth 1)으로 빠른 처리
 * 3. git log로 커밋 정보 수집
 */

const fs = require('fs');
const path = require('path');
const { execSync, spawnSync } = require('child_process');
const os = require('os');

// 임시 디렉토리
const TEMP_BASE = path.join(os.tmpdir(), 'gogs-sync');

function ensureTempDir() {
  if (!fs.existsSync(TEMP_BASE)) {
    fs.mkdirSync(TEMP_BASE, { recursive: true });
  }
}

function gitCloneAndAnalyze(repoUrl, projectName) {
  const tempDir = path.join(TEMP_BASE, projectName.replace(/[^a-z0-9-]/g, ''));

  // 기존 디렉토리 제거
  if (fs.existsSync(tempDir)) {
    execSync(`rm -rf "${tempDir}"`, { stdio: 'ignore' });
  }

  try {
    // 전체 커밋 히스토리 클론 (depth 제약 제거)
    console.log(`   ⏳ Cloning ${projectName}...`);
    execSync(`git clone --quiet "${repoUrl}" "${tempDir}"`, {
      stdio: 'pipe',
      timeout: 60000,
    });

    // 커밋 정보 수집
    const gitLogOutput = execSync(
      'git log --format="%aI|%an" --all',
      {
        cwd: tempDir,
        encoding: 'utf-8',
        stdio: 'pipe',
      }
    ).trim();

    const commits = gitLogOutput.split('\n').filter(line => line.trim());
    const totalCommits = commits.length;

    // 90일 이내 커밋 계산
    const now = new Date();
    const ninetyDaysAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);

    const commit90d = commits.filter(line => {
      const [timestamp] = line.split('|');
      const commitDate = new Date(timestamp);
      return commitDate >= ninetyDaysAgo;
    }).length;

    // 마지막 커밋 작성자
    const lastCommitLine = commits[0];
    let lastCommitAuthor = 'Unknown';
    if (lastCommitLine) {
      const [, author] = lastCommitLine.split('|');
      lastCommitAuthor = author || 'Unknown';
    }

    // 마지막 커밋 날짜
    let updatedAt = new Date().toISOString();
    if (lastCommitLine) {
      const [timestamp] = lastCommitLine.split('|');
      updatedAt = new Date(timestamp).toISOString();
    }

    // 정리
    execSync(`rm -rf "${tempDir}"`, { stdio: 'ignore' });

    return {
      commit_count: totalCommits,
      commit_count_90d: commit90d,
      last_commit_author: lastCommitAuthor,
      updated_at: updatedAt,
      success: true,
    };
  } catch (error) {
    // 정리
    if (fs.existsSync(tempDir)) {
      execSync(`rm -rf "${tempDir}"`, { stdio: 'ignore' });
    }

    return {
      commit_count: 0,
      commit_count_90d: 0,
      last_commit_author: 'Unknown',
      updated_at: new Date().toISOString(),
      success: false,
      error: error.message.split('\n')[0],
    };
  }
}

async function syncViaGit(projectsJsonPath) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  console.log(`🔄 Syncing metadata for ${projects.length} projects via git clone...\n`);

  ensureTempDir();

  let updated = 0;
  let failed = 0;
  let skipped = 0;

  // 순차 처리 (동시 클론은 너무 무겁다)
  for (let i = 0; i < projects.length; i++) {
    const project = projects[i];
    const repoUrl = project.repo_url || project.gogs_path;

    if (!repoUrl || repoUrl.startsWith('/')) {
      skipped++;
      console.log(`⏭️  [SKIP] ${project.name} (no GOGS URL)`);
      continue;
    }

    // GOGS URL 검증
    if (!repoUrl.includes('gogs.dclub.kr')) {
      skipped++;
      console.log(`⏭️  [SKIP] ${project.name} (not GOGS URL)`);
      continue;
    }

    process.stdout.write(`[${i + 1}/${projects.length}] ${project.name.padEnd(40)}`);

    const result = gitCloneAndAnalyze(repoUrl, project.name);

    if (result.success) {
      project.commit_count = result.commit_count;
      project.commit_count_90d = result.commit_count_90d;
      project.last_commit_author = result.last_commit_author;
      project.updated_at = result.updated_at;
      updated++;

      console.log(` ✅ ${result.commit_count} commits, ${result.commit_count_90d} in 90d`);
    } else {
      failed++;
      console.log(` ❌ ${result.error}`);
    }

    // 진행률
    if ((i + 1) % 10 === 0) {
      console.log(`\n📊 Progress: ${updated}/${i + 1} updated, ${failed}/${i + 1} failed\n`);
    }
  }

  // 파일 저장
  const outputPath = projectsJsonPath.replace('.json', '-with-metadata.json');
  const output = Array.isArray(data) ? projects : { ...data, projects };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  // 통계
  console.log('\n' + '='.repeat(60));
  console.log('📊 Sync Summary:');
  console.log(`   ✅ Updated: ${updated} projects`);
  console.log(`   ❌ Failed: ${failed} projects`);
  console.log(`   ⏭️  Skipped: ${skipped} projects`);
  console.log(`   📁 Output: ${outputPath}`);
  console.log('='.repeat(60) + '\n');

  // 정리
  try {
    execSync(`rm -rf "${TEMP_BASE}"`, { stdio: 'ignore' });
  } catch (e) {
    // 무시
  }

  return { updated, failed, skipped, outputPath };
}

// CLI Entry Point
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node sync-via-git-universal.js <projects-with-gogs-urls.json>');
  console.error('예제: node sync-via-git-universal.js ~/kim-project-cli/projects-with-gogs-urls.json');
  process.exit(1);
}

(async () => {
  try {
    const result = await syncViaGit(projectsJsonPath);
    console.log(`✨ 동기화 완료! ${result.updated}개 프로젝트 성공`);
  } catch (error) {
    console.error('❌ 오류:', error.message);
    process.exit(1);
  }
})();

