#!/usr/bin/env node

/**
 * P1-3: 완전 커밋 히스토리 수집 (depth 제약 없음)
 *
 * 이전: git clone --depth 1 (최신 커밋만)
 * 현재: git clone (전체 히스토리) → git log 전체 분석
 *
 * 의도: 정확한 커밋 수를 기반으로 Health Score 재계산
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// GOGS 저장소 목록 로드
const gogsFile = '/data/data/com.termux/files/home/kim-project-cli/gogs-all-repos.json';
const inputFile = '/data/data/com.termux/files/home/kim-project-cli/projects-with-gogs-urls-with-metadata-enhanced.json';
const outputFile = '/data/data/com.termux/files/home/kim-project-cli/projects-with-full-commits.json';

if (!fs.existsSync(gogsFile)) {
  console.error(`❌ gogs-all-repos.json not found at ${gogsFile}`);
  process.exit(1);
}

if (!fs.existsSync(inputFile)) {
  console.error(`❌ Input file not found at ${inputFile}`);
  process.exit(1);
}

const gogs = JSON.parse(fs.readFileSync(gogsFile, 'utf-8'));
const data = JSON.parse(fs.readFileSync(inputFile, 'utf-8'));
const projects = Array.isArray(data) ? data : data.projects || [];

console.log(`📊 전체 커밋 히스토리 수집 (${projects.length}개 프로젝트)\n`);

const tempDir = '/tmp/freelang-sync-full';
if (fs.existsSync(tempDir)) {
  execSync(`rm -rf "${tempDir}"`, { stdio: 'ignore' });
}
fs.mkdirSync(tempDir, { recursive: true });

let successCount = 0;
let failCount = 0;
const commits = {};

projects.forEach((project, idx) => {
  const gitUrl = project.git_url;
  if (!gitUrl) {
    console.log(`⚠️  ${idx + 1}/${projects.length} ${project.name} - git_url 없음`);
    return;
  }

  const projectDir = path.join(tempDir, project.name);

  try {
    // 전체 히스토리 클론 (depth 제약 없음)
    console.log(`🔄 ${idx + 1}/${projects.length} ${project.name}...`);
    execSync(`git clone --quiet "${gitUrl}" "${projectDir}" 2>/dev/null`, {
      timeout: 30000,
      stdio: 'ignore',
    });

    // 모든 커밋 수집
    const logOutput = execSync(
      `cd "${projectDir}" && git log --oneline 2>/dev/null | wc -l`,
      { encoding: 'utf-8' }
    ).trim();

    const totalCommits = parseInt(logOutput) || 0;

    // 90일 커밋 수
    const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000)
      .toISOString()
      .split('T')[0];

    const logOutput90 = execSync(
      `cd "${projectDir}" && git log --since="${ninetyDaysAgo}" --oneline 2>/dev/null | wc -l`,
      { encoding: 'utf-8' }
    ).trim();

    const commits90 = parseInt(logOutput90) || 0;

    // 최종 커밋 시간
    const lastCommit = execSync(
      `cd "${projectDir}" && git log -1 --format=%aI 2>/dev/null`,
      { encoding: 'utf-8' }
    ).trim();

    commits[project.name] = {
      commit_count: totalCommits,
      commit_count_90d: commits90,
      updated_at: lastCommit || project.updated_at,
    };

    console.log(`   ✅ ${totalCommits} commits (${commits90} in 90d)`);
    successCount++;

    // 임시 디렉토리 정리
    execSync(`rm -rf "${projectDir}"`, { stdio: 'ignore' });
  } catch (error) {
    console.log(`   ❌ 실패: ${error.message.split('\n')[0]}`);
    failCount++;
  }
});

// 데이터 병합
console.log(`\n📊 결과 병합...\n`);

const updated = projects.map((project) => {
  if (commits[project.name]) {
    return {
      ...project,
      commit_count: commits[project.name].commit_count,
      commit_count_90d: commits[project.name].commit_count_90d,
      updated_at: commits[project.name].updated_at,
    };
  }
  return project;
});

fs.writeFileSync(outputFile, JSON.stringify(updated, null, 2));

// 통계
console.log('='.repeat(70));
console.log('✨ 전체 커밋 히스토리 수집 완료!\n');
console.log(`✅ 성공: ${successCount}개`);
console.log(`❌ 실패: ${failCount}개`);
console.log(`📊 총: ${successCount + failCount}개 / ${projects.length}개 (${((successCount / projects.length) * 100).toFixed(1)}%)\n`);

// 분포
const distribution = {
  'commits0': updated.filter((p) => !p.commit_count || p.commit_count === 0).length,
  'commits1-5': updated.filter((p) => p.commit_count && p.commit_count >= 1 && p.commit_count <= 5).length,
  'commits6-20': updated.filter((p) => p.commit_count && p.commit_count >= 6 && p.commit_count <= 20).length,
  'commits20-50': updated.filter((p) => p.commit_count && p.commit_count >= 21 && p.commit_count <= 50).length,
  'commits50+': updated.filter((p) => p.commit_count && p.commit_count > 50).length,
};

console.log('📈 커밋 분포:');
Object.entries(distribution).forEach(([cat, count]) => {
  const pct = ((count / updated.length) * 100).toFixed(1);
  console.log(`   ${cat}: ${count}개 (${pct}%)`);
});

const totalCommits = updated.reduce((sum, p) => sum + (p.commit_count || 0), 0);
const avgCommits = Math.round(totalCommits / updated.length);

console.log(`\n📌 평균 커밋: ${avgCommits}개`);
console.log(`📌 총 커밋: ${totalCommits}개`);
console.log(`\n📁 출력: ${outputFile}\n`);
console.log('='.repeat(70) + '\n');

