const fs = require('fs');

// 최종 메타데이터 로드
const metaFile = '/data/data/com.termux/files/home/kim-project-cli/projects-with-full-commits-scored-final-with-archived-status.json';
const data = JSON.parse(fs.readFileSync(metaFile, 'utf-8'));

console.log('📊 Health Score 최종 재계산\n');
console.log('='.repeat(70) + '\n');

// 활성 프로젝트만 필터 (archived 제외)
const activeProjects = data.filter(p => p.status !== 'archived');

// Activity Score 재계산
const updateProjectScores = (projects) => {
  return projects.map(proj => {
    // Activity Score 재계산 (더 정확한 공식)
    const commits = proj.commit_count || 0;
    const commits90d = proj.commit_count_90d || 0;

    // Activity: 기본 30점 + 커밋당 1.4점 (최대 70점) + 90일내 활동 보너스 10점
    const commitScore = Math.min(30 + (commits * 1.4), 100);
    const bonus90d = commits90d > 0 ? 10 : 0;
    const activityScore = Math.min(commitScore + bonus90d, 100);

    // 문서화 점수 (기존)
    const docScore = proj.documentation_score || 50;

    // 테스트 점수 (개선: phase 5에서 추가하면 +10점)
    const hasTest = proj.commit_count > 20 ? 60 : 40; // 가정
    const testScore = hasTest;

    // 커뮤니티 점수
    const communityScore = proj.status === 'archived' ? 5 : 50;

    // 최종 Health Score
    const finalScore = Math.round(
      activityScore * 0.45 + 
      docScore * 0.30 + 
      testScore * 0.15 + 
      communityScore * 0.10
    );

    return {
      ...proj,
      activity_score: Math.round(activityScore),
      documentation_score: docScore,
      testing_score: testScore,
      community_score: communityScore,
      health_score: finalScore
    };
  });
};

const updatedProjects = updateProjectScores(activeProjects);

// 통계
const scores = updatedProjects.map(p => p.health_score);
const avgScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
const maxScore = Math.max(...scores);
const minScore = Math.min(...scores);

// 등급별 분포
const grades = {
  'A+ (90-100)': updatedProjects.filter(p => p.health_score >= 90).length,
  'A (80-89)': updatedProjects.filter(p => p.health_score >= 80 && p.health_score < 90).length,
  'B+ (70-79)': updatedProjects.filter(p => p.health_score >= 70 && p.health_score < 80).length,
  'B (60-69)': updatedProjects.filter(p => p.health_score >= 60 && p.health_score < 70).length,
  'C (50-59)': updatedProjects.filter(p => p.health_score >= 50 && p.health_score < 60).length,
  'D (40-49)': updatedProjects.filter(p => p.health_score >= 40 && p.health_score < 50).length,
  'F (0-39)': updatedProjects.filter(p => p.health_score < 40).length
};

console.log('📈 상위 15개 프로젝트:\n');
const top15 = updatedProjects.sort((a, b) => b.health_score - a.health_score).slice(0, 15);
top15.forEach((p, i) => {
  const grade = p.health_score >= 90 ? 'A+' : p.health_score >= 80 ? 'A' : p.health_score >= 70 ? 'B+' : p.health_score >= 60 ? 'B' : p.health_score >= 50 ? 'C' : p.health_score >= 40 ? 'D' : 'F';
  console.log(`${i + 1}. ${p.name.padEnd(35)} ${p.health_score}/100 (${grade}) - ${p.commit_count} commits`);
});

console.log('\n' + '='.repeat(70) + '\n');
console.log('📊 Health Score 요약:\n');
console.log(`평균: ${avgScore}/100`);
console.log(`최고: ${maxScore}/100`);
console.log(`최저: ${minScore}/100\n`);

console.log('등급 분포:\n');
Object.entries(grades).forEach(([grade, count]) => {
  const pct = ((count / updatedProjects.length) * 100).toFixed(1);
  const bar = '█'.repeat(Math.floor(count / 2));
  console.log(`${grade.padEnd(15)} : ${count.toString().padStart(2)}개 (${pct.padStart(5)}%) ${bar}`);
});

